patch:
diff --git a/repro/no-lonely-if-dangling-else.js b/repro/no-lonely-if-dangling-else.js
new file mode 100644
index 0000000..40a114d
--- /dev/null
+++ b/repro/no-lonely-if-dangling-else.js
@@ -0,0 +1,59 @@
+"use strict";
+
+/*
+ * Reproduction: no-lonely-if autofix rebinds a dangling `else` when the
+ * reported `else { if ... }` belongs to an `if` that is itself the brace-less
+ * consequent of an outer `if`.
+ */
+
+const assert = require("node:assert");
+const path = require("node:path");
+
+// Set ESLINT_DIR to an installed eslint package (e.g. eslint@9.12.0) to test that version instead of this checkout.
+const eslintDir = process.env.ESLINT_DIR || path.resolve(__dirname, "..");
+const { Linter } = require(path.join(eslintDir, "lib/api"));
+const espree = require(require.resolve("espree", { paths: [eslintDir] }));
+
+console.log("ESLint", require(path.join(eslintDir, "package.json")).version, "from", eslintDir);
+
+const code = [
+    "/* eslint no-lonely-if: \"error\" */",
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');"
+].join("\n");
+
+const linter = new Linter({ configType: "flat" });
+const messages = linter.verify(code, [], "repro.js");
+const { output, fixed } = linter.verifyAndFix(code, [], "repro.js");
+
+console.log("Messages:", messages.map(m => `${m.line}:${m.column} ${m.ruleId} ${m.message}`));
+console.log("Fixed:", fixed);
+console.log("--- input ---\n" + code);
+console.log("--- autofix output ---\n" + output);
+
+/** Returns the outer `if`'s alternate type (where `else throw` is bound). */
+function outerAlternate(src) {
+    const ast = espree.parse(src, { ecmaVersion: "latest" });
+    const outer = ast.body.find(n => n.type === "IfStatement");
+
+    return outer.alternate && outer.alternate.type;
+}
+
+/** Runs the code and reports whether it threw. */
+function throws(src) {
+    try {
+        new Function(src)(); // eslint-disable-line no-new-func -- repro
+        return false;
+    } catch {
+        return true;
+    }
+}
+
+console.log("outer if alternate: input =", outerAlternate(code), ", output =", outerAlternate(output));
+console.log("throws at runtime:  input =", throws(code), ", output =", throws(output));
+
+assert.strictEqual(outerAlternate(output), outerAlternate(code), "autofix moved the `else throw` to a different `if`");
+assert.strictEqual(throws(output), throws(code), "autofix changed runtime behavior");
+console.log("OK: autofix preserved semantics");
